        if my_hp <= 2:
            bid = min(my_budget, DAILY_SALARY * 0.95)
        elif my_hp <= 5:
            bid = min(my_budget, DAILY_SALARY * 0.7)
        else:
            bid = min(my_budget, DAILY_SALARY * 0.5)
